#include <bits/stdc++.h>
using namespace std;

using S = pair<int, int>;

#include <atcoder/dsu>
using namespace atcoder;

int d(S p, S q) { return abs(p.first - q.first) + abs(p.second - q.second); }

int main() {
  int N, Q;
  cin >> N >> Q;

  vector<S> xy;
  for (int i = 0; i < N; i++) {
    int x, y;
    cin >> x >> y;
    xy.push_back({x, y});
  }

  dsu uf(N + Q);

  using T = array<int, 3>;
  auto cmp = [](const T& a, const T& b) { return a[0] > b[0]; };
  priority_queue<T, vector<T>, decltype(cmp)> pq(cmp);

  for (int i = 0; i < N; i++) {
    for (int j = i + 1; j < N; j++) {
      pq.push({d(xy[i], xy[j]), i, j});
    }
  }

  while (Q--) {
    int t;
    cin >> t;
    if (t == 1) {
      int x, y;
      cin >> x >> y;
      int n = xy.size();
      xy.push_back({x, y});
      for (int i = 0; i < n; i++) {
        pq.push({d(xy[i], xy[n]), i, n});
      }
    }
    if (t == 2) {
      int ans = -1;
      while (!pq.empty()) {
        auto [mn, u, v] = pq.top();
        pq.pop();
        if (!uf.same(u, v)) {
          ans = mn;
          uf.merge(u, v);
          while (!pq.empty()) {
            auto [mn2, u2, v2] = pq.top();
            if (mn2 != mn) break;
            pq.pop();
            uf.merge(u2, v2);
          }
          break;
        }
      }
      cout << ans << endl;
    }
    if (t == 3) {
      int u, v;
      cin >> u >> v;
      u--;
      v--;
      cout << (uf.same(u, v) ? "Yes" : "No") << endl;
    }
  }
}
